-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.import_site_content_before_site_files(p_request_id uuid, p_bundle jsonb, p_source_heads jsonb)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.import_site_content_before_site_files(p_request_id uuid, p_bundle jsonb, p_source_heads jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid; result uuid; item jsonb; section jsonb; reference record; asset uuid; was_imported boolean; table_name text;
BEGIN
  actor:=app.require_actor();
  IF NOT app.is_super_admin() THEN RAISE EXCEPTION 'only a super admin may import a site' USING ERRCODE='CMS02'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(p_request_id::text,61));
  was_imported:=EXISTS(SELECT 1 FROM app.site_content_imports WHERE request_id=p_request_id);
  -- The previous command verifies the complete bundle fingerprint on retries.
  result:=app.import_site_content_before_recipes(p_request_id,p_bundle,p_source_heads);
  IF was_imported THEN RETURN result; END IF;
  FOREACH table_name IN ARRAY ARRAY['document_metadata','page_recipes','page_recipe_versions'] LOOP
    IF p_bundle ? table_name AND (jsonb_typeof(p_bundle->table_name) IS DISTINCT FROM 'array' OR jsonb_array_length(p_bundle->table_name)>20000) THEN
      RAISE EXCEPTION 'invalid recipe or document archive list' USING ERRCODE='CMS04'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_bundle->'document_metadata','[]')) entry GROUP BY entry.value->>'asset_id' HAVING count(*)>1) THEN
    RAISE EXCEPTION 'duplicate document metadata' USING ERRCODE='CMS04'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(p_bundle->'document_metadata','[]')) LOOP
    IF jsonb_typeof(item->'category') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'archived') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'invalid document metadata' USING ERRCODE='CMS04'; END IF;
    UPDATE public.site_document_metadata SET category=item->>'category',archived=(item->>'archived')::boolean
      WHERE site_id=result AND asset_id=(item->>'asset_id')::uuid;
    IF NOT FOUND THEN RAISE EXCEPTION 'document metadata names an unavailable PDF' USING ERRCODE='CMS04'; END IF;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(p_bundle->'page_recipes','[]')) LOOP
    INSERT INTO public.page_recipes(id,site_id,name,revision,current_version_id,retired_at)
      VALUES((item->>'id')::uuid,result,item->>'name',(item->>'revision')::bigint,NULL,(item->>'retired_at')::timestamptz);
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(p_bundle->'page_recipe_versions','[]')) LOOP
    IF NOT EXISTS(SELECT 1 FROM public.page_versions WHERE id=(item->>'source_version_id')::uuid AND site_id=result)
      OR NOT EXISTS(SELECT 1 FROM public.page_recipes WHERE id=(item->>'recipe_id')::uuid AND site_id=result AND revision>=(item->>'revision')::bigint)
      OR (item->>'revision')::bigint<1 OR jsonb_typeof(item->'content') IS DISTINCT FROM 'array'
      OR jsonb_array_length(item->'content') NOT BETWEEN 1 AND 100 THEN
      RAISE EXCEPTION 'invalid recipe history or source' USING ERRCODE='CMS04'; END IF;
    -- Retain historical retired pins; use_page_recipe rechecks present usability.
    FOR section IN SELECT value FROM jsonb_array_elements(item->'content') LOOP
      IF NOT EXISTS(SELECT 1 FROM public.section_defs d JOIN public.section_def_versions v ON v.section_def_id=d.id
        WHERE d.site_id=result AND d.placement='page' AND d.id::text=section->>'section_def_id' AND v.version::text=section->>'section_def_version')
        OR section ?| ARRAY['raw_html','custom_css'] THEN
        RAISE EXCEPTION 'invalid recipe definition pin or source override' USING ERRCODE='CMS04'; END IF;
    END LOOP;
    FOR asset IN SELECT app.site_asset_references(item->'content') LOOP
      IF NOT EXISTS(SELECT 1 FROM public.site_assets WHERE site_id=result AND id=asset) THEN
        RAISE EXCEPTION 'foreign recipe document' USING ERRCODE='CMS04'; END IF;
    END LOOP;
    FOR reference IN SELECT * FROM app.media_references_in_page_content(item->'content') LOOP
      IF NOT EXISTS(SELECT 1 FROM public.media WHERE site_id=result AND id=reference.media_id) THEN
        RAISE EXCEPTION 'foreign recipe media' USING ERRCODE='CMS04'; END IF;
    END LOOP;
    INSERT INTO public.page_recipe_versions(id,recipe_id,site_id,revision,source_version_id,content,created_at,created_by)
      VALUES((item->>'id')::uuid,(item->>'recipe_id')::uuid,result,(item->>'revision')::bigint,(item->>'source_version_id')::uuid,item->'content',(item->>'created_at')::timestamptz,actor);
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(COALESCE(p_bundle->'page_recipes','[]')) LOOP
    IF item->>'current_version_id' IS NULL THEN RAISE EXCEPTION 'recipe is missing its current version' USING ERRCODE='CMS04'; END IF;
    UPDATE public.page_recipes SET current_version_id=(item->>'current_version_id')::uuid WHERE id=(item->>'id')::uuid AND site_id=result;
  END LOOP;
  RETURN result;
END $function$
